func utAnswer(ans *port.Cells, id int32, nlines int32, xh int32, w int32, osd int32, oconf int32) int32 {
	// An OCR answer of `nlines` lines, each of one word "Hi" 40 pixels high and `w` wide, whose row x-height is `xh` (0: the engine says none); OSD says `osd` degrees
	// at the confidence `oconf` (x10; -1 for no OSD). Answers where it is.
	var at int32 = plan.AnOcr(ans, id)
	var k int32 = 0
	var word int32 = 0
	for k < nlines {
		word = plan.AnOcrWord(ans, at, 10, 20+(k*60), w, 40, 900, k, 0)
		plan.AnOcrCp(ans, word, 72)
		plan.AnOcrCp(ans, word, 105)
		k += 1
	}
	ocr.OxBegin(ans, 0, 0, 0, 0, osd, 1281455214, 100, oconf, nlines, 1, 0, 0, 0)
	k = 0
	for k < nlines {
		ocr.OxLine(ans, 10, 20+(k*60), w, 40, 10, 55+(k*60), 10+w, 55+(k*60), 0, 0, 0, xh, 14, 6)
		k += 1
	}
	ocr.OxBlock(ans, 10, 20, w, nlines*60, 0, 0, 0)
	k = 0
	for k < nlines {
		ocr.OxWord(ans, 0, 0, -1, 0)
		k += 1
	}
	plan.AnOcrEnd(ans, at)
	return at
}

func utFactor(nlines int32, xh int32, pxw int32, pxh int32, osd int32, oconf int32) int32 {
	var ans *port.Cells = port.NewCells()
	var at int32 = utAnswer(ans, 272, nlines, xh, 200, osd, oconf)
	return upscale.UpFactor(ans, at, pxw, pxh, port.NewCells())
}

func TestTheEffectiveResolutionIsWhatTenPointTypeAtThatXHeightHas(emonT *testing.T) {
	port.AssertEq(emonT, upscale.UpEffDpi100(21), 30240, "an x-height of 21 pixels is ten point type at 302 dpi")
	port.AssertEq(emonT, upscale.UpEffDpi100(6), 8640, "6 pixels: 86 dpi, the 90 dpi page of the smoke review")
	port.AssertEq(emonT, upscale.UpEffDpi100(0), 0, "none")
	port.AssertEq(emonT, upscale.UpEffDpi100(-3), 0, "none")
}

func TestTheTypicalXHeightIsTheMedianWeightedByWidth(emonT *testing.T) {
	var ans *port.Cells = port.NewCells()
	var hist *port.Cells = port.NewCells()
	var at int32 = utAnswer(ans, 272, 5, 6, 300, -1, -1)
	var ext int32 = ocr.OxFind(ans, at)
	port.AssertEq(emonT, upscale.UpXheight(ans, ext, hist), 6, "five lines of 6 pixels")
	port.AssertEq(emonT, port.CellsLen(hist), 101, "the histogram is made")
	var ans2 *port.Cells = port.NewCells()
	var at2 int32 = utAnswer(ans2, 272, 3, 0, 300, -1, -1)
	var ext2 int32 = ocr.OxFind(ans2, at2)
	port.AssertEq(emonT, upscale.UpXheight(ans2, ext2, hist), 18, "the engine says none: 45 per cent of the 40 pixel box")
}

func TestSmallTextIsReadAgainEnlargedToAnXHeightOfTwenty(emonT *testing.T) {
	port.AssertEq(emonT, utFactor(5, 6, 765, 990, -1, -1), 4, "6 pixels: 20 / 6 is 4 (the most)")
	port.AssertEq(emonT, utFactor(5, 7, 765, 990, -1, -1), 3, "7 pixels: 3")
	port.AssertEq(emonT, utFactor(5, 10, 765, 990, -1, -1), 2, "10 pixels: 2")
	port.AssertEq(emonT, utFactor(5, 15, 765, 990, -1, -1), 2, "15 pixels: under 16, 2")
	port.AssertEq(emonT, utFactor(5, 16, 765, 990, -1, -1), 1, "16 pixels: the text reads well, not at all")
	port.AssertEq(emonT, utFactor(5, 21, 765, 990, -1, -1), 1, "300 dpi: not at all")
	port.AssertEq(emonT, utFactor(5, 3, 765, 990, -1, -1), 4, "never more than `up-max`")
}

func TestAFirstPassThatReadAlmostNothingOfASmallRasterIsReadAgainThreeTimesAsLarge(emonT *testing.T) {
	// a 450 x 150 PNG of a table (smoke review A9): the engine found no line to measure
	port.AssertEq(emonT, utFactor(2, 0, 450, 150, -1, -1), 3, "two words of a small raster: enlarged 3 times")
	port.AssertEq(emonT, utFactor(0, 0, 450, 150, -1, -1), 3, "no word")
	port.AssertEq(emonT, utFactor(2, 0, 2550, 3300, -1, -1), 1, "the same of a page-sized raster: it is blank, or no text")
	port.AssertEq(emonT, utFactor(2, 0, 1400, 900, -1, -1), 3, "at the limit of `up-rescue-side`")
	port.AssertEq(emonT, utFactor(2, 0, 1401, 900, -1, -1), 1, "over it")
}

func TestAPageTheEngineIsSureIsTurnedIsReadUprightFirst(emonT *testing.T) {
	port.AssertEq(emonT, utFactor(5, 6, 765, 990, 90, 200), 1, "turned a quarter, OSD sure (confidence 20.0): its lines say nothing of the size")
	port.AssertEq(emonT, utFactor(5, 6, 765, 990, 180, 500), 1, "turned a half")
	port.AssertEq(emonT, utFactor(5, 6, 765, 990, 0, 500), 4, "upright and sure: measured")
	port.AssertEq(emonT, utFactor(5, 6, 765, 990, 90, 10), 4, "turned but OSD unsure (confidence 1.0): measured")
}

func TestARasterWhoseEnlargementWouldPassThePixelBoundIsEnlargedLess(emonT *testing.T) {
	port.AssertEq(emonT, utFactor(5, 6, 2000, 2000, -1, -1), 2, "4 million pixels: 2 times is 16 million, 3 times 36 million")
	port.AssertEq(emonT, utFactor(5, 6, 3000, 3000, -1, -1), 1, "9 million: not even twice (36 million)")
	port.AssertEq(emonT, upscale.UpMax(), 4, "the factor is at most 4")
	port.AssertEq(emonT, upscale.UpXhTrigger(), 16, "and the trigger is 16 pixels")
}

func TestAReadingScoresWhatItRead(emonT *testing.T) {
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var at int32 = utAnswer(a, 272, 2, 6, 100, -1, -1)
	var bt int32 = utAnswer(b, 272, 4, 6, 100, -1, -1)
	port.AssertEq(emonT, upscale.UpScore(a, at), 224, "two words of two letters at 900: 2 * (900 * 2 / 16)")
	port.AssertEq(emonT, upscale.UpScore(b, bt), 448, "four words")
	port.AssertThat(emonT, upscale.UpScore(b, bt) > upscale.UpScore(a, at), "reading more scores more")
}

func TestTheCubicsWeightsSumToOneInEveryPhase(emonT *testing.T) {
	var wt *port.Cells = port.NewCells()
	var k int32 = 2
	for k <= 4 {
		upscale.UpWeights(wt, k)
		var r int32 = 0
		for r < (2 * k) {
			port.AssertEq(emonT, (port.CellsAt(wt, r*4)+port.CellsAt(wt, (r*4)+1))+(port.CellsAt(wt, (r*4)+2)+port.CellsAt(wt, (r*4)+3)), 1024, "the four weights of a phase sum to 1024")
			r += 1
		}
		k += 1
	}
	upscale.UpWeights(wt, 2)
	port.AssertEq(emonT, port.CellsAt(wt, 0), 0, "phase 0 (the input pixel's centre): the pixel itself")
	port.AssertEq(emonT, port.CellsAt(wt, 1), 1024, "all of it")
}

func TestAnEnlargedRasterKeepsFlatInkAndEdges(emonT *testing.T) {
	var s *port.BitmapSet = port.NewBitmapSet()
	var src *port.Bitmap = port.BmsPut(s, 7, 4, 3, 1)
	var wt *port.Cells = port.NewCells()
	var y int32 = 0
	var x int32 = 0
	// left half black (0), right half white (255); the third row all 120
	for y < 3 {
		x = 0
		for x < 4 {
			if y == 2 {
				port.BitmapSetU8(src, x, y, 0, 120)
			} else if x >= 2 {
				port.BitmapSetU8(src, x, y, 0, 255)
			} else {
				port.BitmapSetU8(src, x, y, 0, 0)
			}
			x += 1
		}
		y += 1
	}
	port.AssertEq(emonT, port.BmsHas(s, 9), 0, "not made yet")
	upscale.UpMake(s, 9, 10, src, 3, wt)
	port.AssertEq(emonT, port.BmsHas(s, 9), 1, "made")
	var big *port.Bitmap = port.BmsGet(s, 9)
	port.AssertEq(emonT, port.BitmapW(big), 12, "3 times as wide")
	port.AssertEq(emonT, port.BitmapH(big), 9, "and as high")
	port.AssertEq(emonT, port.BitmapChannels(big), 1, "one channel")
	port.AssertEq(emonT, port.BitmapU8(big, 0, 7, 0), 120, "a flat row stays flat: its left")
	port.AssertEq(emonT, port.BitmapU8(big, 11, 7, 0), 120, "and its right")
	port.AssertEq(emonT, port.BitmapU8(big, 6, 7, 0), 120, "and its middle")
	x = 1
	for x < 12 {
		port.AssertThat(emonT, port.BitmapU8(big, x, 0, 0) >= port.BitmapU8(big, x-1, 0, 0), "an edge rises left to right: no ring below the black")
		x += 1
	}
	port.AssertEq(emonT, port.BitmapU8(big, 0, 0, 0), 0, "black at the left")
	port.AssertEq(emonT, port.BitmapU8(big, 11, 0, 0), 255, "white at the right")
}
